/**
 * errors = error findings + threshold failures. `passed` follows `fail-on`:
 * `error` → no errors; `warning` → no errors and no warnings; `never` → always true (reporting mode).
 */
export function summarize(pages, thresholdFailures, failOn) {
    const count = (sev) => pages.reduce((n, p) => n + p.findings.filter((f) => f.severity === sev).length, 0);
    const errors = count('error') + thresholdFailures.length;
    const warnings = count('warning');
    const passed = failOn === 'never' ? true : failOn === 'warning' ? errors + warnings === 0 : errors === 0;
    return { errors, warnings, passed, thresholdFailures };
}
export function buildReport(baseUrl, pages, thresholdFailures, failOn, now = new Date()) {
    return {
        version: 1,
        baseUrl,
        generatedAt: now.toISOString(),
        pages,
        summary: summarize(pages, thresholdFailures, failOn),
    };
}
