import * as core from '@actions/core';
import { COMMENT_MARKER } from '../report/markdown.js';
/** Pull request number from the event payload, or undefined for any other event. */
export function pullRequestNumber(payload) {
    return payload.pull_request?.number;
}
/** Octokit → CommentApi for one issue/PR. */
export function octokitCommentApi(octokit, repo, issue_number) {
    return {
        list: () => octokit.paginate(octokit.rest.issues.listComments, { ...repo, issue_number, per_page: 100 }),
        create: async (body) => void (await octokit.rest.issues.createComment({ ...repo, issue_number, body })),
        update: async (comment_id, body) => void (await octokit.rest.issues.updateComment({ ...repo, comment_id, body })),
    };
}
/**
 * `update` mode edits the comment carrying the marker (or creates it); `new` always creates.
 * A 403 (read-only fork token) only produces a warning.
 */
export async function postComment(api, body, mode, marker = COMMENT_MARKER) {
    try {
        if (mode === 'update') {
            const existing = (await api.list()).find((c) => c.body?.includes(marker));
            if (existing) {
                await api.update(existing.id, body);
                return 'updated';
            }
        }
        await api.create(body);
        return 'created';
    }
    catch (e) {
        if (e.status === 403) {
            core.warning('Could not post the PR comment: the token is read-only (fork PR?). The report is in the job summary; see docs/forks.md.');
            return 'skipped';
        }
        throw e;
    }
}
